/* eslint-disable react-refresh/only-export-components */
import { createContext, useContext, type ReactNode } from 'react';
import type { Theme } from '@docshunt/docs-editor-wasm';

import type { ImageItem } from '@/routes/_authenticated/start/-components/steps/Step4ImageSelect';
import type {
  DraftPromptProfile,
  DraftTemplateOption
} from '@/routes/_authenticated/start/-components/steps/draftTemplateProfile';
import type {
  StartPromptMode,
  StartPromptState,
  StartSelectedDocumentInfo
} from '@/routes/_authenticated/start/-startFlow.types';

interface StartFlowContextValue {
  draftTemplates: DraftTemplateOption[];
  isDraftTemplatesLoading: boolean;
  isDraftTemplatesError: boolean;
  refetchDraftTemplates: () => Promise<unknown>;
  selectedDraftTemplate: DraftTemplateOption | null;
  setSelectedDraftTemplate: (template: DraftTemplateOption | null) => void;
  resetFromTemplateEntry: () => Promise<void>;
  templateName: string;
  selectedTemplateFileId: string | null;
  selectedPromptProfile: DraftPromptProfile;
  prompt: string;
  setPrompt: (value: string) => void;
  promptState: StartPromptState;
  setPromptMode: (mode: StartPromptMode) => void;
  setIdeaText: (value: string) => void;
  setAiAnswers: (answers: Record<string, string>) => void;
  hasUpload: boolean;
  setHasUpload: (value: boolean) => void;
  selectedDocument: StartSelectedDocumentInfo | null;
  setSelectedDocument: (doc: StartSelectedDocumentInfo | null) => void;
  referenceFiles: File[];
  setReferenceFiles: (files: File[]) => Promise<void>;
  isReferenceFilesProcessing: boolean;
  setReferenceFilesProcessing: (value: boolean) => void;
  images: ImageItem[];
  setImages: (images: ImageItem[]) => void;
  hasGeneratedSuggestions: boolean;
  setHasGeneratedSuggestions: (value: boolean) => void;
  theme?: Theme;
  setTheme: (theme: Theme | undefined) => void;
  language: 'ko';
  exportedProductId: string | null;
  setExportedProductId: (id: string | null) => void;
  generateStartToken: number;
  goToVisualSuggestions: () => void;
  startGenerate: () => void;
  resetFlow: () => Promise<void>;
  clearCompletedFlow: () => Promise<void>;
}

const StartFlowContext = createContext<StartFlowContextValue | null>(null);

export function StartFlowProvider({
  value,
  children
}: {
  value: StartFlowContextValue;
  children: ReactNode;
}) {
  return (
    <StartFlowContext.Provider value={value}>
      {children}
    </StartFlowContext.Provider>
  );
}

export function useStartFlow() {
  const context = useContext(StartFlowContext);

  if (!context) {
    throw new Error('useStartFlow must be used within StartFlowProvider');
  }

  return context;
}
